insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_146'
from (values
('127.889.d.23.A',3,'A mechanic points to the places where blankets wrap the hot section of a turbine engine on a nacelle diagram. She is:','["identifying the location of turbine engine insulation blankets", "buying blankets", "ignoring blankets", "painting blankets"]'::jsonb,0,'Blanket spots.','original'),
('127.889.d.23.A',4,'Insulation blankets on a turbine engine are usually placed around the:','["tires", "combustor and turbine sections", "windows", "seats"]'::jsonb,1,'Hot section.','original'),
('127.889.d.23.B',3,'A student traces arrows showing cooling air entering the inlet, flowing around the case and leaving through the cowl. She is:','["ignoring airflow", "describing seats", "identifying turbine engine cooling air flow", "describing tires"]'::jsonb,2,'Cooling flow.','original'),
('127.889.d.23.B',4,'Turbine nacelle cooling air generally exits through:','["the seats", "the tank", "the tires", "outlets in the cowling"]'::jsonb,3,'Exit path.','original'),
('127.889.d.23.C',3,'A mechanic checks ducts and baffle seals on a turbine engine for cracks, tears and loose clamps. She is:','["inspecting rigid or flexible turbine engine cooling ducting or baffle seals", "painting ducts", "ignoring ducts", "cutting ducts"]'::jsonb,0,'Duct check.','original'),
('127.889.d.23.C',4,'A flexible cooling duct that is torn should be:','["taped forever", "repaired or replaced", "ignored", "painted"]'::jsonb,1,'Torn duct.','original'),
('127.889.d.23.D',3,'A student labels the anti-ice valve, the inlet heater and the ice detector on a turbine engine''s ice and rain protection system. She is:','["labeling seats", "labeling lights", "identifying turbine engine ice and rain protection system components", "labeling tires"]'::jsonb,2,'Ice protection.','original'),
('127.889.d.23.D',4,'Engine anti-ice systems often use hot bleed air to:','["freeze the fuel", "cool the inlet", "stop the engine", "warm the inlet lip and prevent ice"]'::jsonb,3,'Bleed anti-ice.','original'),
('127.889.d.24.A',3,'A student labels the exhaust pipes, mufflers and tailpipes on a piston exhaust, and the exhaust cone on a turbine. She is:','["identifying the components of reciprocating and turbine engine exhaust systems", "labeling seats", "labeling tires", "labeling lights"]'::jsonb,0,'Exhaust parts.','original'),
('127.889.d.24.A',4,'A turbine exhaust cone helps to:','["hold fuel", "shape and smooth the flow of exhaust gases", "cool the cabin", "add oil"]'::jsonb,1,'Exhaust cone.','original'),
('127.889.d.24.B',3,'A student explains how exhaust gases leave the cylinders, pass through a collector and exit to the outside. She is:','["describing tires", "ignoring exhaust", "explaining the operational theory of reciprocating and turbine engine exhaust systems", "describing seats"]'::jsonb,2,'Exhaust theory.','original'),
('127.889.d.24.B',4,'A well-designed exhaust system carries gases away so that they:','["burn oil", "stay in", "heat the cabin", "do not re-enter the engine or the cabin"]'::jsonb,3,'Exhaust direction.','original'),
('127.889.d.24.C',3,'A student reads that exhaust parts are hot and can crack from heat and vibration. She is researching:','["the risks of maintenance and inspection of exhaust system components", "no risks", "tire brands", "paint choices"]'::jsonb,0,'Exhaust risk.','original'),
('127.889.d.24.C',4,'Before inspecting a hot exhaust system, a mechanic should:','["ignore burns", "let it cool and use proper protective gear", "touch it hot", "start the engine"]'::jsonb,1,'Cool first.','original'),
('127.889.d.24.D',3,'A student reads that a cracked exhaust can let carbon monoxide leak into the cabin heater air. She is researching:','["tire brands", "no risks", "the risks of operating reciprocating engines with exhaust system defects", "paint choices"]'::jsonb,2,'CO risk.','original'),
('127.889.d.24.D',4,'A carbon monoxide leak from an exhaust crack is dangerous because the gas is:','["harmless", "cool", "visible", "colorless and odorless but poisonous"]'::jsonb,3,'CO danger.','original'),
('127.889.d.24.E',3,'A student reads about the heat, noise and blast behind a running aircraft engine on the ramp. She is researching:','["the risks of ground operation of aircraft engines", "paint choices", "no risks", "tire brands"]'::jsonb,0,'Ground run.','original'),
('127.889.d.24.E',4,'People and equipment behind a running turbine engine can be hurt by:','["quiet air", "the hot, high-speed exhaust blast", "cool air", "still air"]'::jsonb,1,'Blast.','original'),
('127.889.d.25.A',3,'A mechanic checks the aircraft''s manual to learn if its exhaust is a muffler, a stack or a collector type. She is:','["guessing", "ignoring the manual", "identifying the type of exhaust system on a particular aircraft", "painting the exhaust"]'::jsonb,2,'Exhaust type.','original'),
('127.889.d.25.A',4,'A heat muffler on a piston engine often also provides:','["fuel", "oil", "coolant", "warmed air for cabin or carburetor heat"]'::jsonb,3,'Muffler heat.','original'),
('127.889.d.25.B',3,'A mechanic looks over exhaust pipes, clamps and joints for cracks, burn-through and loose hardware. She is:','["inspecting an exhaust system", "ignoring exhaust", "cutting exhaust", "painting exhaust"]'::jsonb,0,'Exhaust check.','original'),
('127.889.d.25.B',4,'Blue or white stains around an exhaust joint often show a:','["fuel leak only", "leak of hot gas", "good seal", "cool joint"]'::jsonb,1,'Leak stain.','original'),
('127.889.d.25.C',3,'A mechanic opens the manual to the steps for testing a thrust reverser that is slow to deploy. She is:','["painting the reverser", "ignoring the reverser", "locating and explaining procedures for testing and troubleshooting a turbine thrust reverser", "guessing"]'::jsonb,2,'Reverser.','original'),
('127.889.d.25.C',4,'A thrust reverser works by:','["adding fuel", "heating the cabin", "cooling the engine", "redirecting exhaust or fan air forward to slow the aircraft"]'::jsonb,3,'How reversers work.','original'),
('127.889.d.25.D',3,'A mechanic pressurizes a piston exhaust with air and listens and sprays soap to find leaks. She is:','["performing a pressure leak check of a reciprocating engine exhaust system", "guessing", "painting the exhaust", "ignoring leaks"]'::jsonb,0,'Leak check.','original'),
('127.889.d.25.D',4,'During a pressure leak check, soapy water bubbles at a joint, which shows:','["a dry joint", "a leak", "a new part", "a good seal"]'::jsonb,1,'Bubbles.','original'),
('127.889.d.26.A',3,'A student explains how a propeller blade acts like a rotating wing that pulls the aircraft forward. She is:','["ignoring propellers", "describing tires", "explaining the theory and operation of propellers", "describing seats"]'::jsonb,2,'Prop theory.','original'),
('127.889.d.26.A',4,'A propeller produces thrust by:','["stopping air", "heating air", "freezing air", "accelerating air backward"]'::jsonb,3,'Thrust.','original'),
('127.889.d.26.B',3,'A student compares fixed-pitch, ground-adjustable and variable-pitch propellers and wood, metal and composite blades. She is:','["identifying types of propellers and blade design", "ignoring propellers", "describing tires", "describing seats"]'::jsonb,0,'Prop types.','original'),
('127.889.d.26.B',4,'A fixed-pitch propeller has blades that:','["fold", "cannot change their angle in flight", "spin backward", "change constantly"]'::jsonb,1,'Fixed pitch.','original'),
('127.889.d.26.C',3,'A student explains how a governor changes blade pitch to hold the propeller rpm steady. She is:','["describing seats", "ignoring governors", "explaining the theory and operation of constant speed propellers and pitch control systems", "describing tires"]'::jsonb,2,'Constant speed.','original'),
('127.889.d.26.C',4,'A constant-speed propeller governor maintains rpm by:','["heating the blades", "changing fuel", "cooling the prop", "adjusting blade angle with oil pressure"]'::jsonb,3,'Governor.','original'),
('127.889.d.26.D',3,'A student explains how a turboprop''s beta range lets the pilot control blade angle directly for taxi and reverse. She is:','["explaining the theory and operation of turbine engine propeller beta range operation", "ignoring beta", "describing tires", "describing seats"]'::jsonb,0,'Beta range.','original'),
('127.889.d.26.D',4,'Beta range operation is used mainly for:','["paint checks", "ground handling and reverse thrust", "high-altitude cruise", "fueling"]'::jsonb,1,'Beta use.','original'),
('127.889.d.26.E',3,'A shop schedules propeller inspections, lubrication and blade checks at each service interval. They are:','["painting propellers", "ignoring propellers", "explaining the purpose and methods of propeller servicing, maintenance and inspection", "avoiding upkeep"]'::jsonb,2,'Prop service.','original'),
('127.889.d.26.E',4,'Nicks and cracks on a propeller blade should be inspected because they can:','["improve thrust", "reduce noise", "cool the blade", "grow and cause blade failure"]'::jsonb,3,'Blade nicks.','original'),
('127.889.d.26.F',3,'A mechanic opens the manual to the steps for removing a propeller from the engine flange and installing it with the correct torque. She is:','["identifying and locating procedures for removal and installation of a propeller", "ignoring the manual", "painting the prop", "guessing"]'::jsonb,0,'Prop removal.','original'),
('127.889.d.26.F',4,'During propeller installation, the mounting bolts must be:','["finger tight", "tightened to the specified torque and safetied", "left loose", "painted over"]'::jsonb,1,'Torque.','original'),
('127.889.d.26.G',3,'A mechanic uses the propeller type certificate data sheet to see the approved diameter, pitch and engine for a propeller. She is:','["ignoring the TCDS", "guessing", "explaining the purpose of the propeller TCDS", "using any prop"]'::jsonb,2,'Prop TCDS.','original'),
('127.889.d.26.G',4,'A propeller TCDS lists approved:','["tire sizes", "seat colors", "radio types", "blade angles, diameter limits and compatible engines"]'::jsonb,3,'TCDS data.','original'),
('127.889.d.26.H',3,'A student explains how a synchrophaser keeps two engines'' propellers at the same rpm and phase to reduce noise and vibration. She is:','["explaining the theory and operation of propeller synchronization systems and propeller deicing systems", "describing seats", "describing tires", "ignoring synchronization"]'::jsonb,0,'Synchronization.','original'),
('127.889.d.26.H',4,'Propeller deicing systems commonly use:','["water spray", "electric heat or fluid to prevent ice on the blades", "cold air", "fuel spray"]'::jsonb,1,'Prop deice.','original'),
('127.889.d.26.I',3,'A student reads that a propeller can start with just a small move and cause serious injury. She is researching:','["paint choices", "no risks", "the risks of propeller ground operation, maintenance and inspection", "tire brands"]'::jsonb,2,'Prop hazard.','original'),
('127.889.d.26.I',4,'When working near a propeller, treat it as if the:','["engine is off forever", "prop is harmless", "switch is safe", "engine could start at any moment"]'::jsonb,3,'Treat as live.','original'),
('127.889.d.27.A',3,'A mechanic rotates each blade to the same position and measures its tip height to confirm they track the same path. She is:','["checking blade static tracking", "guessing", "ignoring tracking", "painting blades"]'::jsonb,0,'Tracking.','original'),
('127.889.d.27.A',4,'Poor blade tracking can cause:','["a cooler prop", "vibration in flight", "less noise", "extra thrust"]'::jsonb,1,'Tracking error.','original'),
('127.889.d.27.B',3,'A mechanic looks over a propeller for nicks, cracks, corrosion and leaks at the hub. She is:','["painting the prop", "ignoring the prop", "inspecting a propeller for condition and airworthiness", "buying a prop"]'::jsonb,2,'Prop inspection.','original'),
('127.889.d.27.B',4,'A crack in a propeller blade is generally cause to:','["fly on", "ignore it", "paint over it", "remove the blade from service"]'::jsonb,3,'Cracks.','original'),
('127.889.d.27.C',3,'A mechanic sets a bubble protractor on the blade at a marked station and reads the angle. She is:','["measuring propeller blade angle", "ignoring blades", "painting blades", "guessing"]'::jsonb,0,'Blade angle.','original'),
('127.889.d.27.C',4,'Blade angle is measured at a:','["hub only", "specified station on the blade", "random spot", "tip only"]'::jsonb,1,'Station.','original'),
('127.889.d.27.D',3,'A mechanic opens the manual to the steps for balancing a fixed-pitch wooden propeller on a balancing stand. She is:','["ignoring balancing", "painting the prop", "locating and explaining the procedures for balancing a fixed-pitch propeller", "guessing"]'::jsonb,2,'Balancing.','original'),
('127.889.d.27.D',4,'An out-of-balance propeller causes:','["smoothness", "extra thrust", "less wear", "vibration and added wear"]'::jsonb,3,'Imbalance.','original'),
('127.889.d.27.E',3,'A mechanic looks at a variable-pitch propeller''s low-pitch and high-pitch stops and the range between them. She is:','["identifying the propeller range of operation", "ignoring stops", "painting stops", "guessing"]'::jsonb,0,'Range.','original'),
('127.889.d.27.E',4,'The pitch range of a variable-pitch propeller is set by its:','["tires", "low and high pitch stops", "seats", "windows"]'::jsonb,1,'Pitch stops.','original'),
('127.889.d.27.F',3,'A mechanic checks the propeller specifications to see if a small blade repair is within the allowed limits. She is:','["guessing", "using any repair", "determining what minor propeller alterations are acceptable using the propeller specifications", "ignoring limits"]'::jsonb,2,'Minor repair.','original'),
('127.889.d.27.F',4,'A minor propeller repair is acceptable only if it:','["looks good", "is quick", "is cheap", "stays within the limits in the specifications"]'::jsonb,3,'Within limits.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
